SELECT 'gongkao', '程度轻重', 'kp-xingce-language-cloze-real-word-degree', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "实词辨析：程度轻重"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "近义词的意思一样，但语气的分量不同。根据语境选择“刚好合适”的力度。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心战法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "结合上下文的关联词。如果有“甚至”、“更”，后面要填重的；如果有“只是”、“不过”，后面要填轻的。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、高频辨析"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "批评 vs 批判：批评轻，批判重（带政治色彩）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "妨碍 vs 妨害：妨碍轻（造成不便），妨害重（造成损害）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "期望 vs 渴望：期望轻，渴望重（非常迫切）。"}]}]}]}]}$$ AS jsonb), NULL, '程度轻重的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "逻辑填空", "程度轻重"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_cloze_real_word_degree", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
